(141727, 2966, 70, '1', '1'),
(141728, 2966, 71, 'It was very HR related to discuss timing. It was rather dry, and mostly focused around whether or not it was burn out and if I needed minimal time off to recover.', 'It was very HR related to discuss timing. It was rather dry, and mostly focused around whether or not it was burn out and if I needed minimal time off to recover.'),
(141729, 2966, 72, '0', '0'),
(141730, 2966, 73, '-1', NULL),
(141731, 2966, 74, '1', '1'),
(141732, 2966, 75, 'It was very secretive and hard conversation, because the air of the place was not to talk about such personal things.', 'It was very secretive and hard conversation, because the air of the place was not to talk about such personal things.'),
(141733, 2966, 76, '4', '4'),
(141734, 2966, 77, '5', '5'),
(141735, 2966, 78, '0', '0'),
