(193851, 3652, 58, '1', '1'),
(193852, 3652, 59, 'I had to tell my manager that my psychiatrist was putting me on a three-month leave for severe depression and anxiety, so I could attend a partial hospitalization program. He was neutrally supportive but clearly uncomfortable with the topic.', 'I had to tell my manager that my psychiatrist was putting me on a three-month leave for severe depression and anxiety, so I could attend a partial hospitalization program. He was neutrally supportive but clearly uncomfortable with the topic.'),
(193853, 3652, 60, '0', '0'),
(193854, 3652, 61, '-1', NULL),
