(236895, 4218, 86, 'reduce stigma. offer options for part time work. not use an EAP as their only mental health coverage.', 'reduce stigma. offer options for part time work. not use an EAP as their only mental health coverage.'),
(236896, 4218, 87, 'I''ve had to drive all of the progress in mental health insurance coverage at my workplace. Before I joined they only offer short term EAP help (designed for grief or a stressful event), and did not offer coverage for an ongoing mental illness. My office visit was in network if I saw a doctor without a MH specialty to prescribe my medication, but was out-of network if I saw a psychiatrist or other provider who specialized in mental health', 'I''ve had to drive all of the progress in mental health insurance coverage at my workplace. Before I joined they only offer short term EAP help (designed for grief or a stressful event), and did not offer coverage for an ongoing mental illness. My office visit was in network if I saw a doctor without a MH specialty to prescribe my medication, but was out-of network if I saw a psychiatrist or other provider who specialized in mental health'),
(236897, 4218, 88, '1', '1'),
(236898, 4218, 89, 'White', 'Blanca');

-- Comprobación: número de filas por tabla
SELECT 'encuestas' AS tabla, COUNT(*) AS filas FROM encuestas
UNION ALL
SELECT 'temas' AS tabla, COUNT(*) AS filas FROM temas
UNION ALL
SELECT 'preguntas' AS tabla, COUNT(*) AS filas FROM preguntas
UNION ALL
SELECT 'paises' AS tabla, COUNT(*) AS filas FROM paises
UNION ALL
SELECT 'tamanos_empresa' AS tabla, COUNT(*) AS filas FROM tamanos_empresa
UNION ALL
SELECT 'personas' AS tabla, COUNT(*) AS filas FROM personas
UNION ALL
SELECT 'respuestas' AS tabla, COUNT(*) AS filas FROM respuestas;
