INSERT INTO preguntas (pregunta_id, tema_id, codigo, pregunta_es, pregunta_en) VALUES
(1, 1, 'edad', '¿Qué edad tienes?', 'What is your age?'),
(2, 1, 'genero', '¿Cuál es tu género?', 'What is your gender?'),
(3, 1, 'pais_residencia', '¿En qué país vives?', 'What country do you live in?'),
(4, 1, NULL, 'Si vives en Estados Unidos, ¿en qué estado o territorio?', 'If you live in the United States, which state or territory do you live in?'),
(5, 1, 'autonomo', '¿Eres autónomo/a?', 'Are you self-employed?'),
(6, 5, 'historial_familiar', '¿Tienes antecedentes familiares de enfermedad mental?', 'Do you have a family history of mental illness?'),
(7, 5, 'tratamiento_alguna_vez', '¿Has buscado alguna vez tratamiento de un profesional de salud mental?', 'Have you ever sought treatment for a mental health disorder from a mental health professional?'),
(8, 1, 'tamano_empresa', '¿Cuántos empleados tiene tu empresa u organización?', 'How many employees does your company or organization have?'),
(9, 1, 'empresa_tech', '¿Tu empleador es principalmente una empresa tecnológica?', 'Is your employer primarily a tech company/organization?'),
(10, 2, 'prestaciones_salud_mental', '¿Tu empleador ofrece prestaciones de salud mental dentro de la cobertura sanitaria?', 'Does your employer provide mental health benefits as part of healthcare coverage?'),
(11, 2, 'anonimato_protegido', '¿Se protege tu anonimato si usas los recursos de salud mental o de adicciones que ofrece tu empleador?', 'Is your anonymity protected if you choose to take advantage of mental health or substance abuse treatment resources provided by your employer?'),
(12, 4, 'lo_contaria_en_entrevista', '¿Mencionarías un problema de salud mental a un posible empleador en una entrevista?', 'Would you bring up a mental health issue with a potential employer in an interview?'),
(13, 1, NULL, '¿Tu puesto principal en la empresa está relacionado con la tecnología/IT?', 'Is your primary role within your company related to tech/IT?'),
(14, 2, 'conoce_opciones_cobertura', '¿Conoces las opciones de atención a la salud mental que incluye la cobertura de tu empleador?', 'Do you know the options for mental health care available under your employer-provided health coverage?'),
(15, 2, 'empresa_hablo_formalmente', '¿Tu empleador ha hablado formalmente alguna vez de salud mental (por ejemplo, en una campaña de bienestar)?', 'Has your employer ever formally discussed mental health (for example, as part of a wellness campaign or other official communication)?'),
(16, 2, 'empresa_ofrece_recursos', '¿Tu empleador ofrece recursos para saber más sobre los trastornos de salud mental y cómo pedir ayuda?', 'Does your employer offer resources to learn more about mental health disorders and options for seeking help?'),
(17, 2, 'facilidad_baja_medica', 'Si un problema de salud mental te llevara a pedir una baja médica, ¿sería fácil o difícil pedirla?', 'If a mental health issue prompted you to request a medical leave from work, how easy or difficult would it be to ask for that leave?'),
(18, 4, 'comodo_hablar_companeros', '¿Te sentirías cómodo/a hablando de un problema de salud mental con tus compañeros?', 'Would you feel comfortable discussing a mental health issue with your coworkers?'),
(19, 4, 'comodo_hablar_supervisor', '¿Te sentirías cómodo/a hablando de un problema de salud mental con tu supervisor directo?', 'Would you feel comfortable discussing a mental health issue with your direct supervisor(s)?'),
(20, 5, NULL, '¿Tienes cobertura médica (privada o pública) que incluya el tratamiento de trastornos de salud mental?', 'Do you have medical coverage (private insurance or state-provided) that includes treatment of mental health disorders?'),
(21, 5, NULL, '¿Conoces recursos locales u online para pedir ayuda por un problema de salud mental?', 'Do you know local or online resources to seek help for a mental health issue?'),
(22, 1, NULL, '¿Has tenido empleadores anteriores?', 'Do you have previous employers?'),
(23, 3, NULL, '¿Tus empleadores anteriores ofrecían prestaciones de salud mental?', 'Have your previous employers provided mental health benefits?'),
(24, 3, NULL, '¿Conocías las opciones de atención a la salud mental que ofrecían tus empleadores anteriores?', 'Were you aware of the options for mental health care provided by your previous employers?'),
(25, 3, NULL, '¿Tus empleadores anteriores hablaron formalmente alguna vez de salud mental?', 'Did your previous employers ever formally discuss mental health (as part of a wellness campaign or other official communication)?'),
(26, 3, NULL, '¿Tus empleadores anteriores ofrecían recursos para saber más sobre los trastornos de salud mental y cómo pedir ayuda?', 'Did your previous employers provide resources to learn more about mental health disorders and how to seek help?'),
(27, 3, NULL, '¿Se protegía tu anonimato al usar los recursos de salud mental o de adicciones de tus empleadores anteriores?', 'Was your anonymity protected if you chose to take advantage of mental health or substance abuse treatment resources with previous employers?'),
(28, 3, NULL, '¿Habrías estado dispuesto/a a hablar de tu salud mental con tus supervisores anteriores?', 'Would you have been willing to discuss your mental health with your direct supervisor(s)?'),
(29, 4, NULL, '¿Mencionarías un problema de salud física a un posible empleador en una entrevista?', 'Would you be willing to bring up a physical health issue with a potential employer in an interview?'),
(30, 4, NULL, '¿Hasta qué punto estarías dispuesto/a a contar a amigos y familia que tienes una enfermedad mental?', 'How willing would you be to share with friends and family that you have a mental illness?'),
(31, 4, NULL, '¿Ver cómo trataron a otra persona que habló de su trastorno mental te ha hecho menos propenso/a a contar el tuyo en tu trabajo actual?', 'Have your observations of how another individual who discussed a mental health disorder made you less likely to reveal a mental health issue yourself in your current workplace?'),
(32, 5, NULL, '¿Has tenido un trastorno de salud mental en el pasado?', 'Have you had a mental health disorder in the past?'),
(33, 5, 'trastorno_actual', '¿Tienes actualmente un trastorno de salud mental?', 'Do you currently have a mental health disorder?'),
(34, 5, 'diagnosticado', '¿Te han diagnosticado alguna vez un trastorno de salud mental?', 'Have you ever been diagnosed with a mental health disorder?'),
(48, 6, 'interfiere_con_tratamiento', 'Si tienes un trastorno de salud mental, ¿con qué frecuencia interfiere en tu trabajo cuando está bien tratado?', 'If you have a mental health disorder, how often do you feel that it interferes with your work when being treated effectively?'),
(49, 6, 'interfiere_sin_tratamiento', 'Si tienes un trastorno de salud mental, ¿con qué frecuencia interfiere en tu trabajo cuando no está bien tratado (cuando tienes síntomas)?', 'If you have a mental health disorder, how often do you feel that it interferes with your work when not being treated effectively (i.e., when you are experiencing symptoms)?'),
(50, 1, NULL, '¿En qué país trabajas?', 'What country do you work in?'),
(51, 1, NULL, '¿En qué estado o territorio de Estados Unidos trabajas?', 'What US state or territory do you work in?'),
(52, 4, NULL, 'Si te han diagnosticado o tratado un trastorno de salud mental, ¿lo cuentas a clientes o contactos profesionales?', 'If you have been diagnosed or treated for a mental health disorder, do you ever reveal this to clients or business contacts?'),
(53, 4, NULL, 'Si te han diagnosticado o tratado un trastorno de salud mental, ¿lo cuentas a compañeros o empleados?', 'If you have been diagnosed or treated for a mental health disorder, do you ever reveal this to coworkers or employees?'),
(54, 6, 'productividad_afectada', '¿Crees que tu productividad se ve afectada alguna vez por un problema de salud mental?', 'Do you believe your productivity is ever affected by a mental health issue?'),
(55, 6, NULL, 'Si es así, ¿qué porcentaje de tu tiempo de trabajo se ve afectado por un problema de salud mental?', 'If yes, what percentage of your work time (time performing primary or secondary job functions) is affected by a mental health issue?'),
(56, 7, 'vio_respuesta_negativa', '¿Has observado o vivido una respuesta poco comprensiva o mal gestionada ante un problema de salud mental en tu trabajo actual o anterior?', 'Have you observed or experienced an unsupportive or badly handled response to a mental health issue in your current or previous workplace?'),
(57, 4, NULL, '¿Te sentirías más cómodo/a hablando con tus compañeros de tu salud física o de tu salud mental?', 'Would you feel more comfortable talking to your coworkers about your physical health or your mental health?'),
(58, 4, NULL, '¿Has hablado alguna vez de tu salud mental con tu empleador?', 'Have you ever discussed your mental health with your employer?'),
(59, 8, NULL, 'Describe la conversación que tuviste con tu empleador sobre tu salud mental: su reacción y qué medidas se tomaron.', 'Describe the conversation you had with your employer about your mental health, including their reactions and what actions were taken to address your mental health issue/questions.'),
(60, 4, NULL, '¿Has hablado alguna vez de tu salud mental con tus compañeros?', 'Have you ever discussed your mental health with coworkers?'),
(61, 8, NULL, 'Describe la conversación que tuviste con tus compañeros sobre tu salud mental, incluida su reacción.', 'Describe the conversation with coworkers you had about your mental health including their reactions.'),
(62, 4, NULL, '¿Algún compañero te ha hablado alguna vez de su salud mental o de la de otro compañero?', 'Have you ever had a coworker discuss their or another coworker''s mental health with you?'),
(63, 8, NULL, 'Describe la conversación que un compañero tuvo contigo sobre su salud mental (sin usar nombres).', 'Describe the conversation your coworker had with you about their mental health (please do not use names).'),
(64, 2, NULL, 'En general, ¿cuánta importancia da tu empleador a la salud física?', 'Overall, how much importance does your employer place on physical health?'),
(65, 2, 'importancia_empresa_salud_mental', 'En general, ¿cuánta importancia da tu empleador a la salud mental?', 'Overall, how much importance does your employer place on mental health?'),
(66, 4, NULL, 'Si has contado a un cliente o contacto profesional que tienes un trastorno de salud mental, ¿cómo te ha afectado a ti o a la relación?', 'If you have revealed a mental health disorder to a client or business contact, how has this affected you or the relationship?'),
(67, 4, NULL, 'Si has contado a un compañero o empleado que tienes un trastorno de salud mental, ¿cómo te ha afectado a ti o a la relación?', 'If you have revealed a mental health disorder to a coworker or employee, how has this impacted you or the relationship?'),
(68, 1, NULL, '¿Tu empleador anterior era principalmente una empresa tecnológica?', 'Was your employer primarily a tech company/organization?'),
(69, 3, NULL, '¿Te habrías sentido más cómodo/a hablando con tu empleador anterior de tu salud física o de tu salud mental?', 'Would you have felt more comfortable talking to your previous employer about your physical health or your mental health?'),
(70, 3, NULL, '¿Hablaste alguna vez de tu salud mental con tu empleador anterior?', 'Did you ever discuss your mental health with your previous employer?'),
(71, 8, NULL, 'Describe la conversación que tuviste con tu empleador anterior sobre tu salud mental: su reacción y qué medidas se tomaron.', 'Describe the conversation you had with your previous employer about your mental health, including their reactions and actions taken to address your mental health issue/questions.'),
(72, 3, NULL, '¿Hablaste alguna vez de tu salud mental con compañeros anteriores?', 'Did you ever discuss your mental health with a previous coworker(s)?'),
(73, 8, NULL, 'Describe la conversación que tuviste con tus compañeros anteriores sobre tu salud mental, incluida su reacción.', 'Describe the conversation you had with your previous coworkers about your mental health including their reactions.'),
(74, 3, NULL, '¿Algún compañero anterior te habló alguna vez de su salud mental o de la de otro compañero?', 'Did you ever have a previous coworker discuss their or another coworker''s mental health with you?'),
(75, 8, NULL, 'Describe la conversación que un compañero anterior tuvo contigo sobre su salud mental (sin usar nombres).', 'Describe the conversation your coworker had with you about their mental health (please do not use names)..1'),
(76, 3, NULL, 'En general, ¿cuánta importancia daba tu empleador anterior a la salud física?', 'Overall, how much importance did your previous employer place on physical health?'),
(77, 3, NULL, 'En general, ¿cuánta importancia daba tu empleador anterior a la salud mental?', 'Overall, how much importance did your previous employer place on mental health?'),
(78, 4, NULL, '¿En tu trabajo se te identifica abiertamente como una persona con un problema de salud mental?', 'Are you openly identified at work as a person with a mental health issue?'),
(79, 4, NULL, '¿Que se te identifique como persona con un problema de salud mental ha afectado a tu carrera?', 'Has being identified as a person with a mental health issue affected your career?'),
(80, 4, NULL, '¿Cómo ha afectado a tu carrera?', 'How has it affected your career?'),
(81, 4, NULL, 'Si supieran que tienes un trastorno de salud mental, ¿cómo crees que reaccionarían tus compañeros de equipo?', 'If they knew you suffered from a mental health disorder, how do you think that your team members/co-workers would react?'),
(82, 8, NULL, 'Describe las circunstancias de la respuesta poco comprensiva o mal gestionada.', 'Describe the circumstances of the badly handled or unsupportive response.'),
(83, 7, 'vio_respuesta_positiva', '¿Has observado o vivido una respuesta comprensiva o bien gestionada ante un problema de salud mental en tu trabajo actual o anterior?', 'Have you observed or experienced supportive or well handled response to a mental health issue in your current or previous workplace?'),
(84, 8, NULL, 'Describe las circunstancias de la respuesta comprensiva o bien gestionada.', 'Describe the circumstances of the supportive or well handled response.'),
(85, 7, 'apoyo_sector_tech', 'En general, ¿qué tan bien crees que el sector tecnológico apoya a los empleados con problemas de salud mental?', 'Overall, how well do you think the tech industry supports employees with mental health issues?'),
(86, 8, NULL, 'Describe brevemente qué podrían hacer el sector en su conjunto o los empleadores para mejorar el apoyo a la salud mental de los empleados.', 'Briefly describe what you think the industry as a whole and/or employers could do to improve mental health support for employees.'),
(87, 8, NULL, 'Si quieres contarnos algo que no se haya preguntado en la encuesta, usa este espacio.', 'If there is anything else you would like to tell us that has not been covered by the survey questions, please use this space to do so.'),
(88, 8, NULL, '¿Estarías dispuesto/a a hablar con nosotros con más detalle sobre tus experiencias con la salud mental en el sector tecnológico?', 'Would you be willing to talk to one of us more extensively about your experiences with mental health issues in the tech industry? (Note that all interview responses would be used _anonymously_ and only with your permission.)'),
(89, 1, NULL, '¿Cuál es tu raza?', 'What is your race?'),
(90, 4, NULL, '¿Crees que hablar de un problema de salud física con tu empleador tendría consecuencias negativas?', 'Do you think that discussing a physical health issue with your employer would have negative consequences?'),
(91, 4, NULL, '¿Sientes que tu empleador se toma la salud mental tan en serio como la salud física?', 'Do you feel that your employer takes mental health as seriously as physical health?'),
(92, 6, 'interfiere_trabajo_2014', 'Si tienes un problema de salud mental, ¿sientes que interfiere en tu trabajo?', 'If you have a mental health condition, do you feel that it interferes with your work?'),
(93, 1, 'teletrabajo_2014', '¿Trabajas en remoto (fuera de la oficina) al menos el 50 % del tiempo?', 'Do you work remotely (outside of an office) at least 50% of the time?'),
(94, 2, NULL, '¿Conoces las opciones de atención a la salud mental que ofrece tu empleador?', 'Do you know the options for mental health care your employer provides?'),
(95, 2, NULL, '¿Tu empleador ha hablado alguna vez de salud mental dentro de un programa de bienestar para empleados?', 'Has your employer ever discussed mental health as part of an employee wellness program?'),
(96, 2, NULL, '¿Tu empleador ofrece recursos para saber más sobre los problemas de salud mental y cómo pedir ayuda?', 'Does your employer provide resources to learn more about mental health issues and how to seek help?'),
(97, 2, 'facilidad_baja_medica_2014', '¿Es fácil pedir una baja médica por un problema de salud mental?', 'How easy is it for you to take medical leave for a mental health condition?'),
(98, 4, 'consecuencias_negativas_2014', '¿Crees que hablar de un problema de salud mental con tu empleador tendría consecuencias negativas?', 'Do you think that discussing a mental health issue with your employer would have negative consequences?'),
(99, 4, 'dispuesto_hablar_companeros_2014', '¿Estarías dispuesto/a a hablar de un problema de salud mental con tus compañeros?', 'Would you be willing to discuss a mental health issue with your coworkers?'),
(100, 4, 'dispuesto_hablar_supervisor_2014', '¿Estarías dispuesto/a a hablar de un problema de salud mental con tu supervisor directo?', 'Would you be willing to discuss a mental health issue with your direct supervisor(s)?'),
(101, 4, NULL, '¿Mencionarías un problema de salud física a un posible empleador en una entrevista?', 'Would you bring up a physical health issue with a potential employer in an interview?'),
(102, 4, NULL, '¿Has oído hablar de consecuencias negativas para compañeros con problemas de salud mental en tu trabajo, o las has visto?', 'Have you heard of or observed negative consequences for coworkers with mental health conditions in your workplace?'),
(103, 8, NULL, 'Notas o comentarios adicionales.', 'Any additional notes or comments'),
(104, 4, 'consecuencias_negativas_2016', '¿Crees que hablar de un trastorno de salud mental con tu empleador tendría consecuencias negativas?', 'Do you think that discussing a mental health disorder with your employer would have negative consequences?'),
(105, 4, NULL, '¿Has oído hablar de consecuencias negativas para compañeros que han hablado abiertamente de su salud mental en tu trabajo, o las has visto?', 'Have you heard of or observed negative consequences for co-workers who have been open about mental health issues in your workplace?'),
(106, 4, NULL, 'Si has contado un problema de salud mental a un cliente o contacto profesional, ¿crees que te ha afectado negativamente?', 'If you have revealed a mental health issue to a client or business contact, do you believe this has impacted you negatively?'),
(107, 4, NULL, 'Si has contado un problema de salud mental a un compañero o empleado, ¿crees que te ha afectado negativamente?', 'If you have revealed a mental health issue to a coworker or employee, do you believe this has impacted you negatively?'),
(108, 3, NULL, '¿Crees que hablar de un trastorno de salud mental con empleadores anteriores habría tenido consecuencias negativas?', 'Do you think that discussing a mental health disorder with previous employers would have negative consequences?'),
(109, 3, NULL, '¿Crees que hablar de un problema de salud física con empleadores anteriores habría tenido consecuencias negativas?', 'Do you think that discussing a physical health issue with previous employers would have negative consequences?'),
(110, 3, NULL, '¿Habrías estado dispuesto/a a hablar de un problema de salud mental con tus compañeros anteriores?', 'Would you have been willing to discuss a mental health issue with your previous co-workers?'),
(111, 3, NULL, '¿Sentías que tus empleadores anteriores se tomaban la salud mental tan en serio como la salud física?', 'Did you feel that your previous employers took mental health as seriously as physical health?'),
(112, 3, NULL, '¿Oíste hablar de consecuencias negativas para compañeros con problemas de salud mental en trabajos anteriores, o las viste?', 'Did you hear of or observe negative consequences for co-workers with mental health issues in your previous workplaces?'),
(113, 4, 'danaria_carrera', '¿Crees que ser identificado/a como persona con un problema de salud mental perjudicaría tu carrera?', 'Do you feel that being identified as a person with a mental health issue would hurt your career?'),
(114, 4, NULL, '¿Crees que tus compañeros te verían de forma más negativa si supieran que tienes un problema de salud mental?', 'Do you think that team members/co-workers would view you more negatively if they knew you suffered from a mental health issue?'),
(115, 5, 'diagnostico', 'Si es así, ¿qué trastornos te han diagnosticado?', 'If yes, what condition(s) have you been diagnosed with?'),
(116, 5, NULL, 'Si crees que quizá lo tienes, ¿qué trastornos crees que tienes?', 'If maybe, what condition(s) do you believe you have?'),
(117, 1, 'puesto', '¿Qué opción describe mejor tu puesto de trabajo?', 'Which of the following best describes your work position?'),
(118, 1, 'teletrabajo_2016', '¿Trabajas en remoto?', 'Do you work remotely?');
