(129707, 2808, 58, '1', '1'),
(129708, 2808, 59, 'I discussed my clinical depression and anxiety with my manager after he had made disparaging remarks about anxiety in a meeting. He was not very receptive to my feedback.', 'I discussed my clinical depression and anxiety with my manager after he had made disparaging remarks about anxiety in a meeting. He was not very receptive to my feedback.'),
(129709, 2808, 60, '1', '1'),
(129710, 2808, 61, 'I have a handful of coworkers that I can talk openly about mental health, including my own. They also have their own struggles, so we''re mutually supporting.', 'I have a handful of coworkers that I can talk openly about mental health, including my own. They also have their own struggles, so we''re mutually supporting.'),
(129711, 2808, 62, '1', '1'),
(129712, 2808, 63, 'A coworker discussed with me his struggles with depression, thoughts of self-harm, and Imposter Syndrome in light of a poor performance review outcome.', 'A coworker discussed with me his struggles with depression, thoughts of self-harm, and Imposter Syndrome in light of a poor performance review outcome.'),
