(145377, 3014, 72, '0', '0'),
(145378, 3014, 73, '-1', NULL),
(145379, 3014, 74, '1', '1'),
(145380, 3014, 75, 'My coworker suffered from depression and anxiety, and wanted the rest of the team to know so that they could understand some of his absences, and some of his interactions with each of us. I used this conversation as a way to check in on him periodically, and help make the environment more accepting and comfortable.', 'My coworker suffered from depression and anxiety, and wanted the rest of the team to know so that they could understand some of his absences, and some of his interactions with each of us. I used this conversation as a way to check in on him periodically, and help make the environment more accepting and comfortable.'),
(145381, 3014, 76, '5', '5'),
(145382, 3014, 77, '5', '5'),
(145383, 3014, 78, '0', '0'),
